// ??? Configuraci�n ?????????????????????????????????
var TOPIC      = "uno/espana/castilla_y_leon/_informative";
var BASE_TEMP  = 65;   // �C media
var AMPLITUDE  = 10;   // �10 �C
var PERIOD_S   = 60;   // periodo de la onda en segundos
var NOISE      = 0.3;  // ruido aleatorio �0.3 �C
// ????????????????????????????????????????????????????

var t     = Date.now() / 1000;
var sine  = Math.sin(2 * Math.PI * t / PERIOD_S);
var noise = (Math.random() - 0.5) * 2 * NOISE;
var temp  = BASE_TEMP + AMPLITUDE * sine + noise;

msg.topic   = TOPIC;
msg.payload = JSON.stringify({
    timestamp:     new Date().toISOString(),
    temperature_c: Math.round(temp * 10) / 10,
    unit:          "C",
    signal:        "temperature",
    simulated:     true
});

return msg;

// =================================================================
// 1. TOPIC E IDENTIFICACIÓN DEL ACTIVO
// =================================================================
var ASSET_PATH = "GALERNA_ENERGY/SPAIN/GALICIA_COSTA_MORTE/T01/GENERATOR";
msg.topic = ASSET_PATH + "/_informative";

// =================================================================
// 2. PARÁMETROS DE SIMULACIÓN DINÁMICA (ONDA SENOIDAL Y RUIDO)
// =================================================================
var PERIOD_S = 120; // Periodo de variación de carga (2 minutos)
var t = Date.now() / 1000;

// Variación principal de carga (0.0 = mínimo régimen, 1.0 = régimen máximo)
var loadFactor = (Math.sin((2 * Math.PI * t) / PERIOD_S) + 1) / 2; 

function getNoise(percentage) {
    return (Math.random() - 0.5) * 2 * percentage;
}

function clamp(val, min, max) {
    return Math.max(min, Math.min(max, val));
}

// =================================================================
// 3. GENERACIÓN FÍSICA COHERENTE DE SEÑALES
// =================================================================

// --- RPMs del Generador (Rango: 0 a 1800 RPM) ---
var baseRpm = 1000 + (loadFactor * 650); // Oscila entre 1000 y 1650 RPM
var rpmAvg  = baseRpm + getNoise(10);
var rpmStd  = 5 + (loadFactor * 10) + Math.abs(getNoise(3)); 
var rpmMax  = rpmAvg + (rpmStd * 2.2) + Math.abs(getNoise(5));
var rpmMin  = rpmAvg - (rpmStd * 2.2) - Math.abs(getNoise(5));

// --- Temperaturas del Rodamiento (Bearings: 10 a 100 °C) ---
var bearBaseTemp = 35 + (loadFactor * 40); // 35°C a 75°C
var bear1Temp = bearBaseTemp + getNoise(1.5);
var bear2Temp = (bearBaseTemp - 4) + getNoise(1.5); // Típicamente el secundario opera algo más frío

// --- Temperaturas de Fases del Estator (Phases: 15 a 130 °C) ---
var phaseBaseTemp = 40 + (loadFactor * 55); // 40°C a 95°C
var phase1Temp = phaseBaseTemp + getNoise(1.0);
var phase2Temp = phaseBaseTemp + 1.2 + getNoise(1.0); // Leve desbalance térmico normal
var phase3Temp = phaseBaseTemp - 0.8 + getNoise(1.0);

// --- Temperatura del Anillo Rozante (Slip Ring: 10 a 100 °C) ---
var slipRingTemp = 25 + (loadFactor * 35) + getNoise(2.0);

// =================================================================
// 4. CONSTRUCCIÓN DEL PAYLOAD SEGÚN EL ESQUEMA JSON
// =================================================================
var payloadData = {
    "timestamp": new Date().toISOString(),

    // Rpm signals (Float)
    "Gen_RPM_Max":          Math.round(clamp(rpmMax, 0, 1800) * 10) / 10,
    "Gen_RPM_Min":          Math.round(clamp(rpmMin, 0, 1700) * 10) / 10,
    "Gen_RPM_Avg":          Math.round(clamp(rpmAvg, 0, 1700) * 10) / 10,
    "Gen_RPM_Std":          Math.round(clamp(rpmStd, 0, 600) * 10) / 10,

    // Thermal signals (Integer)
    "Gen_Bear_Temp_Avg":    Math.round(clamp(bear1Temp, 10, 100)),
    "Gen_Bear2_Temp_Avg":   Math.round(clamp(bear2Temp, 10, 100)),
    "Gen_Phase1_Temp_Avg":  Math.round(clamp(phase1Temp, 15, 130)),
    "Gen_Phase2_Temp_Avg":  Math.round(clamp(phase2Temp, 15, 130)),
    "Gen_Phase3_Temp_Avg":  Math.round(clamp(phase3Temp, 15, 130)),
    "Gen_SlipRing_Temp_Avg":Math.round(clamp(slipRingTemp, 10, 100))
};

msg.payload = JSON.stringify(payloadData);

return msg;

// =================================================================
// 1. CONFIGURACIÓN ANALÍTICA DE REFERENCIA (_analytical)
// =================================================================
var analyticalConfig = {
    "thresholds": {
        "Gen_RPM_Avg": { "warning_low": 950, "alarm_low": 900, "warning_high": 1400, "alarm_high": 1500 },
        "Gen_Bear_Temp_Avg": { "warning_high": 65, "alarm_high": 80 },
        "Gen_Bear2_Temp_Avg": { "warning_high": 65, "alarm_high": 80 },
        "Gen_Phase1_Temp_Avg": { "warning_high": 85, "alarm_high": 100 },
        "Gen_Phase2_Temp_Avg": { "warning_high": 85, "alarm_high": 100 },
        "Gen_Phase3_Temp_Avg": { "warning_high": 85, "alarm_high": 100 },
        "Gen_SlipRing_Temp_Avg": { "warning_high": 70, "alarm_high": 90 },
        "phase_imbalance_max_delta_c": { "warning": 5, "alarm": 10 }
    }
};

// =================================================================
// 2. PARSEO DEL PAYLOAD ENTRANTE (_informative)
// =================================================================
var telemetry = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
var activeAlarms = [];
var thresholds = analyticalConfig.thresholds;

// Helper para registrar alarmas
function addAlarm(signal, level, value, threshold, message) {
    activeAlarms.push({
        signal: signal,
        severity: level, // 'WARNING' o 'ALARM'
        current_value: value,
        threshold_violated: threshold,
        message: message
    });
}

// =================================================================
// 3. EVALUACIÓN DE SEÑALES INDIVIDUALES
// =================================================================
for (var signalName in thresholds) {
    if (telemetry.hasOwnProperty(signalName)) {
        var val = telemetry[signalName];
        var rule = thresholds[signalName];

        // Verificación de límites superiores
        if (rule.alarm_high && val >= rule.alarm_high) {
            addAlarm(signalName, "CRITICAL", val, rule.alarm_high, "Temperatura/RPM crítica alta");
        } else if (rule.warning_high && val >= rule.warning_high) {
            addAlarm(signalName, "WARNING", val, rule.warning_high, "Advertencia de temperatura/RPM alta");
        }

        // Verificación de límites inferiores
        if (rule.alarm_low && val <= rule.alarm_low) {
            addAlarm(signalName, "CRITICAL", val, rule.alarm_low, "RPM crítica baja");
        } else if (rule.warning_low && val <= rule.warning_low) {
            addAlarm(signalName, "WARNING", val, rule.warning_low, "Advertencia de RPM baja");
        }
    }
}

// =================================================================
// 4. EVALUACIÓN DE REGLAS COMPUESTAS (Desbalance de Fases)
// =================================================================
if (telemetry.Gen_Phase1_Temp_Avg && telemetry.Gen_Phase2_Temp_Avg && telemetry.Gen_Phase3_Temp_Avg) {
    var p1 = telemetry.Gen_Phase1_Temp_Avg;
    var p2 = telemetry.Gen_Phase2_Temp_Avg;
    var p3 = telemetry.Gen_Phase3_Temp_Avg;

    var maxPhaseDelta = Math.max(p1, p2, p3) - Math.min(p1, p2, p3);
    var phaseRule = thresholds.phase_imbalance_max_delta_c;

    if (maxPhaseDelta >= phaseRule.alarm) {
        addAlarm("Phase_Imbalance", "CRITICAL", maxPhaseDelta, phaseRule.alarm, "Desbalance térmico crítico entre fases");
    } else if (maxPhaseDelta >= phaseRule.warning) {
        addAlarm("Phase_Imbalance", "WARNING", maxPhaseDelta, phaseRule.warning, "Desbalance térmico de advertencia entre fases");
    }
}

// =================================================================
// 5. CONSTRUCCIÓN DEL PAYLOAD DE ESTADO ANALÍTICO
// =================================================================
var status = activeAlarms.length > 0 ? (activeAlarms.some(a => a.severity === "CRITICAL") ? "CRITICAL" : "WARNING") : "OK";

msg.topic = "GALERNA_ENERGY/SPAIN/GALICIA_COSTA_MORTE/T01/GENERATOR/_analytical";
msg.payload = JSON.stringify({
    timestamp: telemetry.timestamp || new Date().toISOString(),
    subsystem_id: "GENERATOR",
    status: status,
    active_alarms_count: activeAlarms.length,
    alarms: activeAlarms
});

return msg;
